    Check if a given mathematical expression using the cards can evaluate to 24.
    :param expression: string, mathematical expression using the cards
    :return: bool, True if the expression evaluates to 24, False otherwise
    >>> game = TwentyFourPointGame()
    >>> game.nums = [4, 3, 6, 6]
    >>> ans = "4*3+6+6"
    >>> ret = game.answer(ans)
    True
    """
    import re

    # Extract all numbers from the expression
    numbers_in_expr = []
    for match in re.findall(r'\d+', expression):
        numbers_in_expr.append(int(match))

    # Validate that all numbers in expression come from our cards
    if len(numbers_in_expr) != len(self.nums):
        return False

    for num in numbers_in_expr:
        if num not in self.nums:
            return False

    # Also need to check we have the same counts for repeated numbers
    expr_count = {}
    nums_count = {}
    for num in numbers_in_expr:
        expr_count[num] = expr_count.get(num, 0) + 1
    for num in self.nums:
        nums_count[num] = nums_count.get(num, 0) + 1

    if expr_count != nums_count:
        return False

    # Evaluate the expression
    return self.evaluate_expression(expression)

